import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第25章 铃铛","description":"","frontmatter":{},"headers":[],"relativePath":"第25章_铃铛.md","filePath":"第25章_铃铛.md"}'),r={name:"第25章_铃铛.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第25章-铃铛" tabindex="-1">第25章 铃铛 <a class="header-anchor" href="#第25章-铃铛" aria-label="Permalink to &quot;第25章 铃铛&quot;">​</a></h1><p>那年春天快要走完的时候，风里有了潮气。</p><p>午休刚结束，教室里还留着饭菜的味道，混着粉笔灰和窗外飘进来的花香。我坐在靠窗的位置，手指压着一张空白纸条，脑子里空空的，什么字也写不出来。</p><p>顾远从后面拍我的肩，低声说，走了，打球去。</p><p>我摇头没动。他叹口气，自己抱着球跑了。</p><p>江苒就是在这个时候进来的。</p><p>她跑得很急，发梢上还沾着汗，脸颊红红的，手里抱着一摞作业本。钥匙就挂在她校服拉链上，一串很小的铃铛，走一步响一下，清清脆脆的。</p><p>她把作业本放在讲台上，转身往座位走。经过我身边时，铃铛忽然勾住了我桌角贴着的胶带。</p><p>叮的一声，很轻。</p><p>她停下来，低头去解，越急越解不开，脸更红了。</p><p>“我来吧。”我说。</p><p>她松开手，退后半步，把位置让给我。铃铛很小，金色的，上面刻着细细的纹路。我捏着那点凉凉的金属，慢慢把胶带拨开。</p><p>“好了。”</p><p>“谢谢。”她笑起来，眼睛弯弯的，“它老是调皮，到处乱勾。”</p><p>我点点头，不知道接什么，只能低头看自己的纸条。</p><p>她却没走，反而在我前面的空位坐下来，反着趴在椅背上看我。</p><p>“沈聿，你中午怎么不去吃饭呀，林小满说在食堂看见你了，你吃得好少。”</p><p>“不太饿。”</p><p>“那可不行，下午还有体育课呢。”她从口袋里摸出一颗糖，放在我桌上，“海盐味的，给你。”</p><p>糖纸是浅蓝色的，摸上去有点凉。我没舍得吃，把它推到书角压好。</p><p>“你总写纸条，写什么呢。”她好奇地凑近。</p><p>我下意识把纸条扣住，手心出了汗。</p><p>她笑出声：“不看不看，我就是好奇。你每次写的时候都皱眉，像个小老头。”</p><p>我摸了摸自己的眉头，好像真的皱着，赶紧松开。</p><p>就在这时，她腰间的钥匙又响了。她起身时动作太大，铃铛撞在椅子腿上，发出一串又脆又乱的响声。</p><p>叮叮，叮叮叮。</p><p>她自己被逗笑了，晃了晃钥匙：“听，像不像有人在里面跑步，跑得摔倒了。”</p><p>我看着那枚小铃铛晃来晃去，忽然想起小时候在外婆家听过的风铃。风吹过来，满院子都是响声，外婆说，响一下，就是风路过一次。</p><p>不知道为什么，我嘴角动了一下。</p><p>一开始只是很轻的一下，后来没忍住，笑出了声。</p><p>很短的一声，连我自己都愣住了。</p><p>江苒也愣住了，眼睛睁得圆圆的。</p><p>“你笑了。”她说。</p><p>“我没有。”我立刻否认，耳朵发烫。</p><p>“你笑了，我听见了。”她往前凑，铃铛又响了一下，“再笑一个嘛。”</p><p>“我不会。”</p><p>“骗人，明明就会。”她托着下巴看我，眼里亮亮的，“沈聿，你笑起来很好看，以后多笑笑。”</p><p>我的脸更烫了，只能转头看窗外。窗外那棵枇杷树的叶子被风吹得翻过来，露出浅浅的背面，阳光落在上面，一闪一闪的。</p><p>她顺着我的目光看过去：“枇杷快熟了吧，等熟了我们去摘。”</p><p>“学校的不让摘。”陈默不知什么时候回来了，抱着一摞书，冷冷地插了一句。</p><p>江苒冲他做了个鬼脸：“我就看看，不摘。”</p><p>陈默把书放下，看了我一眼，又看看江苒，没再说话。</p><p>上课铃响了，江苒赶紧跑回座位，铃铛一路响回去，像一串小小的脚步。</p><p>那节是叶老师的课，讲作文。她说，文字要有味道，要让人闻到摸到。我低头在草稿纸上写，风是潮的，糖是咸的，铃铛是凉的。</p><p>写完我自己看了很久，又划掉了。</p><p>下午的体育课，云压得很低，跑道被晒得发软，踩上去有股橡胶的热味。林小满和何晓在树荫下分橘子汽水喝，瓶盖起开时嗤的一声，甜香一下就散开了。顾远非要拉我跑接力，我摆手不去，就坐在旁边看。轮到江苒跑时，她把钥匙解下来塞进口袋，可铃铛还是露出一角，跑一步响一下，围观的人都笑了。她跑完红着脸回来，额头上全是汗，问我，听见没，我带着铃铛跑，像不像赶着一群小铃铛回家。我点点头，把自己的汽水递给她。她接过去喝了一口，眼睛亮亮的，说，好甜，你也喝。我说好，却一直没喝，只觉得瓶身凉凉的，贴着掌心很舒服。</p><p>下课后，顾远一身汗地回来，拿起我桌上的橘子汽水灌了一大口，喘着气说：“你刚才笑什么呢，老远就听见江苒在闹你。”</p><p>“没什么。”</p><p>“还装。”他撞撞我的肩，“全班都没听你大声笑过，你小子可以啊。”</p><p>我推开他，心里却有点异样的开心，像薄荷水滑过喉咙，凉凉的，散开。</p><p>放学的时候，天阴了下来，空气闷闷的，像要下雨。</p><p>我在车棚那边锁车，听见身后叮叮两声，回头一看，是江苒。她推着车，钥匙在风里晃。</p><p>“好巧。”她说。</p><p>我们一起往校门口走，谁也没说话，只有铃铛偶尔响一下，混着车轮压过小石子的声音。</p><p>走到分岔路口，她忽然停下来，从书包侧袋里掏出一个小东西，塞进我手里。</p><p>我摊开手，是颗纸星星，也是她送我的第一颗。</p><p>折得很仔细，浅黄色的纸，角角都压得平平的，放在掌心轻飘飘的，没什么分量。</p><p>“送你。”她有点不好意思，捏了捏衣角，“我跟林小满学的，折了好多颗，这颗折得最好。”</p><p>“为什么送我。”我问。</p><p>“因为你今天笑了呀。”她晃晃钥匙，铃铛清脆地响，“笑是要奖励的。这颗星星给你攒着，等你攒多了，可以许愿。”</p><p>我握紧那颗星星，纸角硌着掌心，有点疼，又有点安心。</p><p>“谢谢。”</p><p>“不用谢。”她骑上车，回头冲我挥手，“明天见，爱皱眉的小老头。”</p><p>铃铛声远了，被风吹散。</p><p>我站在原地，看着她的背影消失在雾气里，才慢慢骑车回家。</p><p>晚上，窗外开始下小雨，雨点打在枇杷叶上，沙沙的。我坐在台灯下，把那颗纸星星放在桌角，看了很久。</p><p>我找来一个空的玻璃瓶，是以前装薄荷水剩下的，洗得很干净。我把星星放进去，瓶子空荡荡的，只有它一颗，晃一下，会轻轻地响。</p><p>妈妈敲门进来，问我怎么还不睡。我把瓶子藏进抽屉，说马上。</p><p>她走后，我又把瓶子拿出来，在纸条上写，今日晴转雨，铃铛响了三次，笑了一次，得星一颗。</p><p>写完觉得太直白，又撕掉重写，只留下四个字，铃铛很响。</p><p>我把纸条折好，压在瓶子底下。</p><p>雨声渐渐大了，带着泥土的腥气。我躺在床上，闭上眼睛，耳边好像还留着那串叮叮的声音。</p><p>迷迷糊糊快睡着的时候，手机在枕头边震了一下，是顾远发来的消息，说明天把收音机调到点歌那档，有首歌很好听，放给我听。</p><p>我回了个好，翻了个身，又想起何晓下午说的话。她说江苒的铃铛是宋阿婆送的，能保平安。我当时没在意，此刻却觉得那响声里藏着什么。他们在旁边起哄，说铃铛一响，沈聿就笑了，以后要靠铃铛叫他起床。我嘴上没理，心里却把那声音记住了。</p><p>就在要睡着的那一秒，我忽然想起，白天解开铃铛的时候，她的钥匙串上好像还有一把小钥匙，生了锈，样子很旧，跟那枚新新的铃铛一点也不配。</p><p>那会是谁的钥匙，她为什么一直带着。</p><p>窗外的雨下得更密了，我心里那点潮气，怎么也晾不干。</p><p>普发下去的那些星星都不算，只有她亲手塞进我手心说攒着可以许愿的那颗才算。</p>',78)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
